/-- The `i`-th face map from `⦋n⦌` to `⦋n+1⦌` -/
def δ {n} (i : Fin (n + 2)) : ⦋n⦌ ⟶ ⦋n + 1⦌ :=
  mkHom (Fin.succAboveOrderEmb i).toOrderHom

def bayesianRisk (E : estimationProblem Θ 𝒴 𝒵) (P : Kernel Θ 𝒳)
    (κ : Kernel 𝒳 𝒵) (π : Measure Θ) : ℝ≥0∞ :=
  ∫⁻ θ, risk E P κ θ ∂π

def condFDiv (f : ℝ → ℝ) (κ η : Kernel α β) (μ : Measure α) : EReal :=
  if (∀ᵐ a ∂μ, fDiv f (κ a) (η a) ≠ ⊤)
    ∧ (Integrable (fun x ↦ (fDiv f (κ x) (η x)).toReal) μ)
  then ((μ[fun x ↦ (fDiv f (κ x) (η x)).toReal] : ℝ) : EReal)
  else ⊤
